public class SyntaxDemo {
    public static void main(String[] args) {
        int count = 3;                 // statements end with a semicolon
        var name = "Ada";              // local type inference (Java 10+)

        // Text block preserves newlines and strips common indentation (Java 15+)
        String report = """
                name: %s
                count: %d
                """.formatted(name, count);

        // Arrow switch: no fall-through, and every branch is exhaustive
        String size = switch (count) {
            case 1 -> "one";
            case 2, 3 -> "few";
            default -> "many";
        };

        List<String> tags = List.of("jvm", "typed");
        System.out.print(report);
        System.out.println(size + " " + tags);
    }
}

