public class TypeChecks {
    public static void main(String[] args) {
        Object value = "cheatsheet";

        // instanceof binds the cast result to a new variable (Java 16+)
        if (value instanceof String text && text.length() > 5) {
            System.out.println(text.toUpperCase());
        }

        // Pattern switch over Object is exhaustive with a default (Java 21)
        String kind = switch (value) {
            case Integer number -> "integer " + number;
            case String text2 -> "string of " + text2.length() + " chars";
            case null -> "null value";
            default -> "other type";
        };

        System.out.println(kind);
    }
}

