// A record generates the constructor, accessors, equals, hashCode and toString
record Point(int x, int y) {
    // Compact constructor validates without repeating the parameters
    public Point {
        if (Math.abs(x) > 1_000 || Math.abs(y) > 1_000) {
            throw new IllegalArgumentException("coordinates out of range");
        }
    }

    Point shift(int dx, int dy) {
        return new Point(x + dx, y + dy);
    }
}

public class RecordDemo {
    public static void main(String[] args) {
        Point start = new Point(2, 5);
        Point moved = start.shift(3, -1);
        System.out.println(start.x() + "," + start.y());   // 2,5
        System.out.println(moved);                          // Point[x=5, y=4]
    }
}

abstract class Shape {
    protected final String name;

    protected Shape(String name) {
        this.name = name;
    }

    public abstract double area();

    public String describe() {
        return name + " with area " + area();
    }
}

class Circle extends Shape {
    private final double radius;

    Circle(double radius) {
        super("circle");
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public String describe() {
        return super.describe() + " (r=" + radius + ")";
    }
}

