    }
}

public class SealedDemo {
    // Only the listed records may implement Payment (Java 17+)
    sealed interface Payment permits CardPayment, CashPayment {}

    record CardPayment(String last4) implements Payment {}
    record CashPayment(int cents) implements Payment {}

    // The compiler knows the cases are exhaustive, so no default is needed
    static String label(Payment payment) {
        return switch (payment) {
            case CardPayment card -> "card ending " + card.last4();
            case CashPayment cash -> "cash " + cash.cents() + " cents";
        };
    }

    public static void main(String[] args) {
        System.out.println(label(new CardPayment("4242")));
        System.out.println(label(new CashPayment(1250)));
    }
}

