public class GenericsDemo {
    static class Box<T> {
        private T value;

        void put(T value) {
            this.value = value;
        }

        T get() {
            return value;
        }
    }

    // The bound allows compareTo and keeps the return type concrete
    static <T extends Comparable<T>> T max(T left, T right) {
        return left.compareTo(right) >= 0 ? left : right;
    }

    public static void main(String[] args) {
        Box<String> box = new Box<>();
        box.put("java");
        System.out.println(box.get());

        System.out.println(max(3, 9));               // 9
        System.out.println(max("apple", "pear"));    // pear
    }
}

import java.util.ArrayList;
import java.util.List;

public class WildcardsDemo {
    // Producer: accepts any list of a Number subtype, reads as Number
    static double sum(List<? extends Number> values) {
        double total = 0;
        for (Number value : values) {
            total += value.doubleValue();
        }
        return total;
    }

    // Consumer: accepts any list that can hold Integer, writes Integer
    static void addInts(List<? super Integer> target) {
        target.add(10);
        target.add(20);
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(1, 2, 3);
        System.out.println(sum(ints));

        List<Number> numbers = new ArrayList<>();
        addInts(numbers);
        System.out.println(numbers);
    }
}

