public class CollectionsDemo {
    public static void main(String[] args) {
        List<String> langs = new ArrayList<>();
        langs.add("java");
        langs.add("kotlin");
        langs.set(1, "scala");
        langs.remove("java");

        Set<String> tags = new HashSet<>();
        tags.add("backend");
        tags.add("backend");             // ignored, a set holds no duplicates

        Map<String, Integer> stock = new HashMap<>();
        stock.put("apple", 12);
        stock.merge("apple", 3, Integer::sum);   // 15
        stock.putIfAbsent("pear", 7);

        int apples = stock.getOrDefault("apple", 0);
        System.out.println(langs + " " + tags + " " + apples);

        // Immutable factories copy nothing and reject mutation (Java 9+)
        List<Integer> primes = List.of(2, 3, 5, 7);
        Map<String, Integer> sizes = Map.of("small", 1, "large", 3);
        System.out.println(primes + " " + sizes);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.TreeMap;

public class OrderedDemo {
    public static void main(String[] args) {
        Deque<String> queue = new ArrayDeque<>();
        queue.addLast("first");
        queue.addLast("second");
        queue.addFirst("priority");

        String next = queue.removeFirst();   // priority
        System.out.println(next + " then " + queue);

        // TreeMap keeps keys in their natural order
        Map<String, Integer> sorted = new TreeMap<>();
        sorted.put("banana", 3);
        sorted.put("apple", 5);
        sorted.put("cherry", 2);

        for (Map.Entry<String, Integer> entry : sorted.entrySet()) {
            System.out.println(entry.getKey() + "=" + entry.getValue());
        }
    }
}

import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

record Employee(String name, String team, int salary) {}

public class StreamDemo {
    public static void main(String[] args) {
        List<Employee> staff = List.of(
                new Employee("Ana", "platform", 8200),
                new Employee("Bruno", "platform", 7400),
                new Employee("Carla", "data", 9100),
                new Employee("Davi", "data", 6800));

        List<String> wellPaid = staff.stream()
                .filter(employee -> employee.salary() > 7000)
                .sorted(Comparator.comparingInt(Employee::salary).reversed())
                .map(Employee::name)
                .toList();                       // Java 16+

        Map<String, Double> averageByTeam = staff.stream()
                .collect(Collectors.groupingBy(
                        Employee::team,
                        Collectors.averagingInt(Employee::salary)));

        long payroll = staff.stream().mapToLong(Employee::salary).sum();

        System.out.println(wellPaid);
        System.out.println(averageByTeam);
        System.out.println(payroll);
    }
}

import java.util.OptionalInt;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class NumericStreams {
    public static void main(String[] args) {
        int[] values = {4, 8, 15, 16, 23, 42};

        int sum = IntStream.of(values).sum();
        OptionalInt max = IntStream.of(values).max();
        double mean = IntStream.of(values).average().orElse(0);

        String evens = IntStream.of(values)
                .filter(number -> number % 2 == 0)
                .mapToObj(Integer::toString)
                .collect(Collectors.joining(", "));

        System.out.println(sum + " " + max.orElse(-1) + " " + mean);
        System.out.println(evens);               // 4, 8, 16, 42
    }
}

public class ExceptionsDemo {
    static int parsePort(String raw) {
        try {
            int port = Integer.parseInt(raw);
            if (port > 65535) {
                throw new IllegalArgumentException("port out of range: " + port);
            }
            return port;
        } catch (NumberFormatException error) {
            // Keep the cause so the original stack trace survives
            throw new IllegalArgumentException("not a number: " + raw, error);
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println(parsePort("8080"));
            System.out.println(parsePort("eighty"));
        } catch (IllegalArgumentException error) {
            System.out.println("bad input: " + error.getMessage());
            System.out.println("cause: " + error.getCause());
        } finally {
            System.out.println("done");
        }
    }
}

