public class TryWithResources {
    public static void main(String[] args) {
        // The reader is closed even when readLine throws
        try (BufferedReader reader = new BufferedReader(new FileReader("notes.txt"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException error) {
            System.err.println("could not read notes.txt: " + error.getMessage());
        }
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class FilesDemo {
    public static void main(String[] args) throws IOException {
        Path path = Path.of("notes.txt");

        // Write and read a whole file as UTF-8 text
        Files.writeString(path, "first line\nsecond line\n");
        String content = Files.readString(path);
        System.out.println(content.lines().count() + " lines");

        // Files.lines is lazy and must be closed
        try (var lines = Files.lines(path)) {
            lines.filter(line -> line.startsWith("second"))
                    .forEach(System.out::println);
        }

        // Files.list is also a closeable stream
        try (var entries = Files.list(Path.of("."))) {
            entries.limit(5).forEach(System.out::println);
        }
    }
}

