import java.time.Duration;
import java.util.concurrent.Executors;

public class VirtualThreadsDemo {
    public static void main(String[] args) {
        // One virtual thread per task, cheap enough for thousands of tasks
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int task = 1; task <= 3; task++) {
                int id = task;
                executor.submit(() -> {
                    Thread.sleep(Duration.ofMillis(200));
                    System.out.println("task " + id + " on " + Thread.currentThread());
                    return id;
                });
            }
        }   // close waits for every submitted task
        System.out.println("all tasks finished");
    }
}

import java.util.concurrent.CompletableFuture;

public class FuturesDemo {
    public static void main(String[] args) {
        CompletableFuture<String> user = CompletableFuture.supplyAsync(() -> "ana");
        CompletableFuture<Integer> score = CompletableFuture.supplyAsync(() -> 87);

        String result = user.thenCombine(score, (name, points) -> name + " scored " + points)
                .exceptionally(error -> "failed: " + error.getMessage())
                .join();

        System.out.println(result);   // ana scored 87
    }
}

