import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class JdbcTransactionDemo {
    public static void main(String[] args) throws SQLException {
        String url = "jdbc:postgresql://localhost:5432/shop";

        try (Connection connection = DriverManager.getConnection(url, "app", "secret")) {
            connection.setAutoCommit(false);

            try (PreparedStatement debit = connection.prepareStatement(
                         "UPDATE account SET balance_cents = balance_cents - ? WHERE id = ?");
                 PreparedStatement credit = connection.prepareStatement(
                         "UPDATE account SET balance_cents = balance_cents + ? WHERE id = ?")) {

                debit.setLong(1, 2500);
                debit.setLong(2, 1);
                debit.executeUpdate();

                credit.setLong(1, 2500);
                credit.setLong(2, 2);
                credit.executeUpdate();

                connection.commit();
            } catch (SQLException error) {
                connection.rollback();
                throw error;
            }
        }
    }
}

