public class NullAndEquals {
    public static void main(String[] args) {
        // NullPointerException: unboxing a null Integer
        Integer count = null;
        // int total = count;                  // would throw NullPointerException
        int total = count == null ? 0 : count; // safe default
        System.out.println(total);

        // == compares references; equals compares characters
        String first = "java";
        String second = new String("java");
        System.out.println(first == second);      // false
        System.out.println(first.equals(second)); // true
    }
}

import java.util.ArrayList;
import java.util.List;

public class DivisionAndIteration {
    public static void main(String[] args) {
        // Integer division truncates, so add a floating point operand
        int half = 5 / 2;              // 2
        double precise = 5 / 2.0;      // 2.5
        System.out.println(half + " vs " + precise);

        // removeIf is safe; removing inside a for-each throws
        // ConcurrentModificationException
        List<String> names = new ArrayList<>(List.of("ana", "bruno", "carla"));
        names.removeIf(name -> name.startsWith("b"));
        System.out.println(names);

        // Valid indexes are 0 through length - 1
        int[] values = {10, 20, 30};
        int last = values[values.length - 1];   // 30
        System.out.println(last);
    }
}

import java.util.HashMap;
import java.util.Map;

public class KeyContract {
    // Records generate equals and hashCode that agree with each other
    record User(String email) {}

    public static void main(String[] args) {
        Map<User, Integer> visits = new HashMap<>();
        visits.put(new User("ana@example.com"), 1);

        // Lookup works because equal records have equal hash codes
        System.out.println(visits.get(new User("ana@example.com")));   // 1

        // A class that overrides equals but not hashCode breaks this lookup
    }
}
